SELECT DATE_TRUNC('MONTH', arrived_date) AS arrived_month, SUM(CASE WHEN body_style = 'pickup' THEN 1 ELSE 0 END) AS pickup_count, AVG(term_months) AS avg_term_months
FROM car_stock
GROUP BY DATE_TRUNC('MONTH', arrived_date);

SELECT * FROM (SELECT CASE WHEN donor_segment IN ('mid', 'grassroots') THEN 'core' ELSE 'other' END AS donor_segment_group, grant_stage, volunteer_hrs FROM grant_awards)
PIVOT (COUNT(volunteer_hrs) FOR grant_stage IN ('applied', 'awarded', 'reported'))
ORDER BY donor_segment_group;

select id, payload_kg, launched_on, mission_state
from payload_items
where mission_state not in ('planned', 'lost') and (mission_state <> 'success' or mission_state in ('partial', 'success'));

SELECT a.id, a.mission_state, a.burn_secs, a.launched_on, (SELECT MAX(b.burn_secs) FROM missions b WHERE b.mission_state = a.mission_state) AS mission_state_max_burn_secs, (SELECT AVG(x.burn_secs) FROM missions x WHERE x.mission_state = 'planned') AS overall_avg_burn_secs
FROM missions a
ORDER BY overall_avg_burn_secs;

SELECT c.id, c.vin_tail
FROM car_stock AS c
WHERE (SELECT COUNT(t.id) FROM test_drives AS t WHERE t.car_stock_id = c.id AND t.drive_mins > 47) >= 2;
